method rolling_max(numbers: seq<int>) returns (result: seq<int>)
    requires |numbers| > 0 // The input list must not be empty
    ensures |result| == |numbers| // The output list has the same length as the input list
    ensures forall i: int :: 0 <= i < |result| ==> result[i] == max(numbers[0..i+1]) // Each element of result is the maximum of the prefix of numbers up to index i
{
    var maxSoFar := numbers[0];
    var resultList := new int[|numbers|];

    // Iterate through the numbers to calculate the rolling max
    for i := 0 to |numbers| - 1 {
        if numbers[i] > maxSoFar {
            maxSoFar := numbers[i]; // Update maxSoFar if current number is greater
        }
        resultList[i] := maxSoFar; // Store the current maximum in the result
    }

    result := resultList; // Return the result list
}
